"""Publish only the reviewed grouped-card checkout and no-preselection backend."""
import argparse,base64,hashlib,importlib.util,json,mimetypes,pathlib,subprocess
ROOT=pathlib.Path(__file__).resolve().parents[2];RELEASE=pathlib.Path('/tmp/opus-pay-release')
s=importlib.util.spec_from_file_location('h',ROOT/'ops/activation/deploy-opus-pay.py');h=importlib.util.module_from_spec(s);s.loader.exec_module(h)
p=argparse.ArgumentParser();p.add_argument('--activate',action='store_true');args=p.parse_args()
current=json.loads((ROOT/'production/current-release.json').read_text());project=h.api(h.PREFIX);assert project['canonical_deployment']['id']==current['deployment_id'],'Live deployment changed; review first'
assert all(project['source']['config'][k]is False for k in ['deployments_enabled','production_deployments_enabled'])
assert {'CF_ACCESS_TEAM_DOMAIN','CF_ACCESS_AUD','RESEND_API_KEY','RECEIPT_FROM_EMAIL'}.issubset(project['deployment_configs']['production']['env_vars'])
assert project['deployment_configs']['production']['env_vars']['PAYMENT_ADMIN_NOTIFY_TO']['value']=='admin@opuszim.co.zw'
before=json.loads((ROOT/current['artifact_directory']/'asset-manifest.json').read_text());assert h.api(h.PREFIX+'/deployments/'+current['deployment_id'])['files']==before
meta=json.loads((RELEASE/'changes.json').read_text());assert meta['baseline_deployment']==current['deployment_id'];generated=json.loads((RELEASE/'manifest.json').read_text())
changed={'/payments/index.html','/payments/index.txt',meta['checkout_chunk'],meta['checkout_css']};assert meta['checkout_chunk'].startswith('/_next/static/chunks/app/payments/page-') and meta['checkout_css'].startswith('/_next/static/css/opus-pay-')
manifest={**before,**{f:generated[f]for f in changed}};assert all(manifest[f]==v for f,v in before.items() if f not in changed)
lock=json.loads((ROOT/'ops/activation/opus-pay-lock.json').read_text());assert all(manifest[f]==v for f,v in lock['assets'].items());bundle=pathlib.Path('/tmp/opus-reconstructed-pages-worker.bundle').read_bytes();digest=hashlib.sha256(bundle).hexdigest();assert digest==lock['backend_bundle_sha256']
for d in (ROOT/'production/workers').iterdir():
 e=json.loads((d/'deployment.json').read_text());assert h.api(f'/accounts/{h.ACCOUNT}/workers/scripts/{d.name}/deployments')['deployments'][0]['versions']==[{'version_id':e['active_version_id'],'percentage':100}]
e=json.loads((ROOT/'ops/site/www-release.json').read_text());assert h.api(f'/accounts/{h.ACCOUNT}/workers/scripts/opus-www-redirect/deployments')['deployments'][0]['versions']==e['active_deployments'][0]['versions']
print(json.dumps({'preflight':'passed','only_checkout_frontend_changes':sorted(changed),'non_payment_frontend_preserved':True,'admin_notifications_preserved':True,'migrations':[],'no_live_payment':True}),flush=True)
if not args.activate:raise SystemExit(0)
assert not subprocess.check_output(['git','status','--porcelain'],cwd=ROOT).strip(),'Commit reviewed changes first';commit=subprocess.check_output(['git','rev-parse','HEAD'],cwd=ROOT,text=True).strip();assert commit==subprocess.check_output(['git','ls-remote','origin','refs/heads/main'],cwd=ROOT,text=True).split()[0]
jwt=h.api(h.PREFIX+'/upload-token')['jwt'];hashes=list(set(manifest.values()));missing=set(h.api('/pages/assets/check-missing',{'hashes':hashes},token=jwt));files={v:f for f,v in manifest.items() if v in missing};assert set(files.values()).issubset(changed),'Unrelated retained asset missing'
for key,f in files.items():h.api('/pages/assets/upload',[{'key':key,'value':base64.b64encode((RELEASE/'assets'/f.lstrip('/')).read_bytes()).decode(),'metadata':{'contentType':mimetypes.guess_type(f)[0]or'application/octet-stream'},'base64':True}],token=jwt)
h.api('/pages/assets/upsert-hashes',{'hashes':hashes},token=jwt);assert not h.api('/pages/assets/check-missing',{'hashes':hashes},token=jwt)
fields={'manifest':json.dumps(manifest),'branch':'main','commit_hash':commit,'commit_message':'One card handoff; let Pesepay choose the card method','commit_dirty':'false','_worker.bundle':('_worker.bundle',bundle),'functions-filepath-routing-config.json':('functions-filepath-routing-config.json',(ROOT/'production/state/pages-function-routes.json').read_bytes()),'_routes.json':('_routes.json',json.dumps({'version':1,'include':['/*'],'exclude':[]}).encode())}
body,ct=h.multipart(fields);deployment=h.api(h.PREFIX+'/deployments',body,'POST',content_type=ct);out=pathlib.Path('/tmp/opus-card-handoff-release');out.mkdir(exist_ok=True);(out/'manifest.json').write_text(json.dumps(manifest,indent=2)+'\n');record={'deployment_id':deployment['id'],'url':deployment['url'],'environment':'production','commit':commit,'baseline':current['deployment_id'],'backend_bundle_sha256':digest,'database_migrations_applied':[],'card_handoff':{'grouped_choice':'International cards & Zimswitch','gateway_method_preselection':False,'checkout_chunk':meta['checkout_chunk'],'checkout_css':meta['checkout_css'],'changed_frontend_files':sorted(changed),'no_live_test_payment':True}};(out/'result.json').write_text(json.dumps(record,indent=2)+'\n');print(json.dumps({'deployment_id':deployment['id'],'url':deployment['url']}))
